   <label>\u958B\u53E3\u3059\u308B\u7AEF<select id="form-wall-opening"><option value="start">\u59CB\u7AEF</option><option value="end">\u7D42\u7AEF</option><option value="both">\u4E21\u7AEF</option></select></label>
